content.query:
// Auto-remediated vs manual incidents
ServiceNowIncidents_CL
| where TimeGenerated {timeRange}
| where Severity_s in ({severity})
| extend IsAutoRemediated = iif(CloseNotes_s has 'auto-remediated' or CloseNotes_s has 'runbook', 'Auto-Remediated', 'Manual')
| summarize Count = count() by IsAutoRemediated
